def read_text(path: Path) -> str:
    # newline="" keeps the original line endings untouched
    with open(path, "r", encoding="utf-8", newline="") as f:
        return f.read()


def write_text(path: Path, text: str):
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write(text)


def test_block_pattern(tc_id: str):
    # <test> elements are not nested, so the first </test> closes the block
    return re.compile(r'<test tcID="' + re.escape(tc_id) + r'">.*?</test>',
                      re.DOTALL)


def block_scores(block: str):
    return [s.strip() for s in re.findall(r'<score value="([^"]*)"', block)]


def find_c2_xml(c2_path: Path) -> Path:
    if c2_path.is_file():
        return c2_path
    if c2_path.name.lower() == "pdmerged":
        candidates = [c2_path / MERGED_XML]
    else:
        candidates = sorted(c2_path.rglob(f"PDMerged/{MERGED_XML}"))
    candidates = [c for c in candidates if c.is_file()]
    if len(candidates) != 1:
        raise SystemExit(f"Expected exactly one PDMerged\\{MERGED_XML} under "
                         f"{c2_path}, found {len(candidates)}: {candidates}")
    return candidates[0]


def step3_copy_c2_results(pdmerged: Path, c2_xml: Path, dry_run: bool):
    target = pdmerged / MERGED_XML
    print(f"\n[Step 3] {target}")
    print(f"  source (C2 EPR): {c2_xml}")
    if not target.is_file():
        print(f"  {MERGED_XML} not found - skipped")
        return
    if target.resolve() == c2_xml.resolve():
        print("  target is the C2 EPR file itself - skipped")
        return

    source_text = read_text(c2_xml)
    text = read_text(target)
    changed = False
    for tc in XML_TEST_CASES:
        pattern = test_block_pattern(tc)
        src = pattern.search(source_text)
        dst = pattern.search(text)
        if not src:
            print(f"  {tc}: not in C2 EPR xml - skipped")
            continue
        if not dst:
            print(f"  {tc}: not in target xml - skipped")
            continue
        if src.group(0) == dst.group(0):
            print(f"  {tc}: already same as C2 EPR")
            continue
        old, new = block_scores(dst.group(0)), block_scores(src.group(0))
        print(f"  {tc}: {old} -> {new}")
        text = text[:dst.start()] + src.group(0) + text[dst.end():]
        changed = True

    if changed and not dry_run:
        backup = target.with_name(target.name + ".bak")
        if not backup.exists():  # keep the very first original
            shutil.copy2(target, backup)
            print(f"  backup: {backup.name}")
        write_text(target, text)
        print("  saved")


